begin;
create temp table fixture(actor uuid default gen_random_uuid(),viewer uuid default gen_random_uuid(),outsider uuid default gen_random_uuid(),company uuid default gen_random_uuid(),other_company uuid default gen_random_uuid(),job uuid default gen_random_uuid(),foreignjob uuid default gen_random_uuid(),candidate uuid default gen_random_uuid(),second uuid default gen_random_uuid(),foreigncandidate uuid default gen_random_uuid(),request uuid default gen_random_uuid());
insert into fixture default values;
grant select on fixture to authenticated,service_role;
create temp table results(name text,passed boolean);
grant insert,select on results to authenticated,service_role,anon;
create function pg_temp.ok(name text,passed boolean) returns void language plpgsql as $$begin if passed is distinct from true then raise exception 'FAILED: %',name;end if;insert into results values(name,true);end$$;
create function pg_temp.denied(name text,statement text,expected text) returns void language plpgsql as $$begin begin execute statement;exception when others then if sqlstate<>expected then raise exception 'FAILED wrong SQLSTATE %: % (%)',sqlstate,name,sqlerrm;end if;insert into results values(name,true);return;end;raise exception 'FAILED unexpectedly allowed: %',name;end$$;
insert into auth.users(id,email,role,aud) select id,id::text||'@report-test.invalid','authenticated','authenticated' from fixture,lateral unnest(array[actor,viewer,outsider]) id;
update public.profiles set full_name='RH sintético' where id=(select actor from fixture);
insert into public.companies(id,name) select company,'Reports A' from fixture union all select other_company,'Reports B' from fixture;
insert into public.company_members(company_id,user_id,role) select company,actor,'owner' from fixture union all select company,viewer,'viewer' from fixture union all select other_company,outsider,'owner' from fixture;
insert into public.jobs(id,company_id,titulo,descricao,criteria) select job,company,'Analista de relatórios','Análise de planilhas e relatórios com Excel.','[{"kind":"skill","text":"Excel","required":true,"weight":5,"min_years":null,"source":null}]'::jsonb from fixture union all select foreignjob,other_company,'Outra empresa','Outra descrição','[]' from fixture;
update public.jobs set approved_hash=private.job_hash(private.job_payload(titulo,descricao,categoria,criteria)) where id=(select job from fixture);
insert into public.candidates(id,company_id,processing_status,review_status,dados_extraidos)
 select candidate,company,'concluido','completed','{"nome_completo":"Ana Sintética","email":"privado@example.invalid","telefone":"11987654321","data_nascimento":"2000-05-08","skills":["Excel"],"formacao_academica":[{"curso":"Administração","instituicao":"Instituição sintética","nivel":"Superior"}]}'::jsonb from fixture
 union all select second,company,'erro','pending','{"nome_completo":"Bruna Sintética"}' from fixture union all select foreigncandidate,other_company,'concluido','completed','{}' from fixture;
select set_config('request.jwt.claims',json_build_object('sub',actor,'role','authenticated')::text,true) from fixture;
set local role authenticated;
select public.set_candidate_job_link(company,candidate,job,true) from fixture;
select public.save_candidate_decision(company,candidate,job,0,'aprovado',true,'Qualificações conferidas pelo RH',gen_random_uuid()) from fixture;
select public.add_candidate_note(company,candidate,job,'Nota da vaga: contato privado@example.invalid e 11987654321',gen_random_uuid()) from fixture;
select public.add_candidate_note(company,candidate,null,'NOTA GERAL NUNCA EXPORTAR',gen_random_uuid()) from fixture;
reset role;
set local role service_role;
select set_config('test.run',public.begin_ranking(actor,company,job,gen_random_uuid())->>'id',true) from fixture;
select public.stage_ranking(actor,current_setting('test.run')::uuid,jsonb_build_array(jsonb_build_object('candidate_id',candidate,'score',100,'details',
 '{"formula":"evidence-v3","criterios":[{"kind":"skill","text":"Excel","required":true,"weight":5,"min_years":null,"estado":"atendido","motivo":"Competência documentada","evidencias":[{"campo":"skills.0","trecho":"Excel - privado@example.invalid 11987654321","pagina":1,"origem":"extracao"}]}]}'::jsonb))) from fixture;
select public.finish_ranking(actor,current_setting('test.run')::uuid) from fixture;
reset role;
set local role authenticated;
select set_config('test.report',public.generate_vacancy_report(company,job,current_setting('test.run')::uuid,array[candidate],false,false,request)::text,true) from fixture;
select set_config('test.access',public.access_vacancy_report(company,current_setting('test.report')::uuid,'view')::text,true) from fixture;
select pg_temp.ok('only chosen candidates included',jsonb_array_length(current_setting('test.access')::jsonb->'report'->'candidates')=1);
select pg_temp.ok('names are opt in',current_setting('test.access')::jsonb->'report'->'candidates'->0->>'label'='Candidato 1');
select pg_temp.ok('generation has real actor time and schema version',current_setting('test.access')::jsonb->'report'->>'created_by'=(select actor::text from fixture) and current_setting('test.access')::jsonb->'report'->>'actor'='RH sintético' and current_setting('test.access')::jsonb->'report'->>'created_at' is not null and current_setting('test.access')::jsonb->'report'->>'schema_version'='1');
select pg_temp.ok('evaluation is dated and versioned',current_setting('test.access')::jsonb->'report'->'evaluation'->>'id'=current_setting('test.run') and current_setting('test.access')::jsonb->'report'->'evaluation'->>'date' is not null and current_setting('test.access')::jsonb->'report'->'job'->>'version' is not null and current_setting('test.access')::jsonb->'report'->'candidates'->0->'versions'->>'data' is not null);
select pg_temp.ok('professional education retained',current_setting('test.access')::jsonb->'report'->'candidates'->0->'qualifications'->'education'->0->>'course'='Administração');
select pg_temp.ok('automatic evidence and RH are separate',current_setting('test.access')::jsonb->'report'->'candidates'->0->'automatic'->>'score'='100' and current_setting('test.access')::jsonb->'report'->'candidates'->0->'rh'->>'status'='aprovado' and current_setting('test.access')::jsonb->'report'->'candidates'->0->'automatic'->'criteria'->0->'evidence'->0->>'origin'='extracao');
select pg_temp.ok('RH author and date preserved',current_setting('test.access')::jsonb->'report'->'candidates'->0->'rh'->'decision'->>'actor_id'=(select actor::text from fixture) and current_setting('test.access')::jsonb->'report'->'candidates'->0->'rh'->'decision'->>'date' is not null);
select pg_temp.ok('no contacts birth originals or unrequested notes in payload',current_setting('test.access') not like '%privado@example.invalid%' and current_setting('test.access') not like '%11987654321%' and current_setting('test.access') not like '%2000-05-08%' and current_setting('test.access') not like '%NOTA GERAL%' and current_setting('test.access') not like '%Nota da vaga%' and current_setting('test.access') not like '%arquivo_path%');
select pg_temp.ok('new report not stale',not (current_setting('test.access')::jsonb->>'outdated_now')::boolean);
select pg_temp.ok('retry reuses immutable report',public.generate_vacancy_report(company,job,current_setting('test.run')::uuid,array[candidate],false,false,request)::text=current_setting('test.report')) from fixture;
select pg_temp.ok('retry does not duplicate generation audit',(select count(*)=1 from public.vacancy_report_events where action='generated'));
select pg_temp.denied('request cannot change selected people',$q$select public.generate_vacancy_report(company,job,current_setting('test.run')::uuid,array[second],false,false,request) from fixture$q$,'22023');
select pg_temp.denied('empty selection denied',$q$select public.generate_vacancy_report(company,job,current_setting('test.run')::uuid,'{}',false,false,gen_random_uuid()) from fixture$q$,'22023');
select pg_temp.denied('duplicate selection denied',$q$select public.generate_vacancy_report(company,job,current_setting('test.run')::uuid,array[candidate,candidate],false,false,gen_random_uuid()) from fixture$q$,'22023');
select pg_temp.denied('null candidate denied',$q$select public.generate_vacancy_report(company,job,current_setting('test.run')::uuid,array[candidate,null],false,false,gen_random_uuid()) from fixture$q$,'22023');
select pg_temp.denied('more than 100 candidates denied',$q$select public.generate_vacancy_report(company,job,current_setting('test.run')::uuid,array_fill(candidate,array[101]),false,false,gen_random_uuid()) from fixture$q$,'22023');
select pg_temp.denied('foreign candidate denied',$q$select public.generate_vacancy_report(company,job,current_setting('test.run')::uuid,array[candidate,foreigncandidate],false,false,gen_random_uuid()) from fixture$q$,'42501');
select pg_temp.denied('foreign vacancy denied',$q$select public.generate_vacancy_report(company,foreignjob,current_setting('test.run')::uuid,array[candidate],false,false,gen_random_uuid()) from fixture$q$,'42501');
select pg_temp.denied('unknown run denied',$q$select public.generate_vacancy_report(company,job,gen_random_uuid(),array[candidate],false,false,gen_random_uuid()) from fixture$q$,'22023');
select pg_temp.denied('null run on retry denied',$q$select public.generate_vacancy_report(company,job,null,array[candidate],false,false,request) from fixture$q$,'22023');
select pg_temp.denied('direct payload access cannot bypass audit',$q$select payload from public.vacancy_reports$q$,'42501');
select pg_temp.denied('browser cannot forge reports',$q$insert into public.vacancy_reports(company_id) select company from fixture$q$,'42501');
select pg_temp.denied('browser cannot rewrite snapshots',$q$update public.vacancy_reports set payload='{}'$q$,'42501');
select pg_temp.denied('browser cannot delete history',$q$delete from public.vacancy_reports$q$,'42501');
select pg_temp.denied('browser cannot forge download audit',$q$insert into public.vacancy_report_events(company_id,report_id,action) select company,current_setting('test.report')::uuid,'pdf' from fixture$q$,'42501');
select pg_temp.denied('browser cannot erase audit',$q$delete from public.vacancy_report_events$q$,'42501');
select public.access_vacancy_report(company,current_setting('test.report')::uuid,'pdf'),public.access_vacancy_report(company,current_setting('test.report')::uuid,'csv') from fixture;
select pg_temp.ok('both download formats audit actual caller',(select count(*)=2 and bool_and(actor_id=(select actor from fixture) and actor_name='RH sintético' and created_at is not null) from public.vacancy_report_events where action in ('pdf','csv')));
select set_config('test.named',public.generate_vacancy_report(company,job,current_setting('test.run')::uuid,array[second,candidate],true,true,gen_random_uuid())::text,true) from fixture;
select set_config('test.named_access',public.access_vacancy_report(company,current_setting('test.named')::uuid,'view')::text,true) from fixture;
select pg_temp.ok('chosen order retained and pending candidate has no invented score',current_setting('test.named_access')::jsonb->'report'->'candidates'->0->>'id'=(select second::text from fixture) and current_setting('test.named_access')::jsonb->'report'->'candidates'->0->'automatic'->>'score' is null and current_setting('test.named_access')::jsonb->'report'->'candidates'->0->'automatic'->>'reason' is not null);
select pg_temp.ok('explicit names and vacancy notes included only',current_setting('test.named_access') like '%Ana Sintética%' and current_setting('test.named_access') like '%Nota da vaga%' and current_setting('test.named_access') not like '%NOTA GERAL%' and current_setting('test.named_access') not like '%privado@example.invalid%');
select public.add_candidate_note(company,candidate,job,'Nota adicional na mesma transação',gen_random_uuid()) from fixture;
select pg_temp.ok('new notes mark report outdated even within same transaction timestamp',(public.access_vacancy_report(company,current_setting('test.named')::uuid,'view')->>'outdated_now')::boolean) from fixture;
select pg_temp.ok('unrequested notes do not invalidate report',not (public.access_vacancy_report(company,current_setting('test.report')::uuid,'view')->>'outdated_now')::boolean) from fixture;
select public.save_candidate_decision(company,candidate,job,1,'em_analise',false,'Revisar após nova entrevista',gen_random_uuid()) from fixture;
select set_config('test.after',public.access_vacancy_report(company,current_setting('test.report')::uuid,'view')::text,true) from fixture;
select pg_temp.ok('RH changes signal outdated snapshot without rewriting it',(current_setting('test.after')::jsonb->>'outdated_now')::boolean and current_setting('test.after')::jsonb->'report'=current_setting('test.access')::jsonb->'report');
reset role;
select set_config('request.jwt.claims',json_build_object('sub',viewer,'role','authenticated')::text,true) from fixture;
set local role authenticated;
select pg_temp.ok('viewer can list authorized reports',(select count(*)=2 from public.vacancy_reports));
select pg_temp.ok('viewer can consult with audit',public.access_vacancy_report(company,current_setting('test.report')::uuid,'view')->'report'->>'id'=current_setting('test.report')) from fixture;
select pg_temp.denied('viewer cannot generate',$q$select public.generate_vacancy_report(company,job,current_setting('test.run')::uuid,array[candidate],false,false,gen_random_uuid()) from fixture$q$,'42501');
select pg_temp.denied('viewer cannot download pdf',$q$select public.access_vacancy_report(company,current_setting('test.report')::uuid,'pdf') from fixture$q$,'42501');
select pg_temp.denied('viewer cannot download csv',$q$select public.access_vacancy_report(company,current_setting('test.report')::uuid,'csv') from fixture$q$,'42501');
select pg_temp.denied('unknown operation denied',$q$select public.access_vacancy_report(company,current_setting('test.report')::uuid,'anything') from fixture$q$,'42501');
reset role;
select set_config('request.jwt.claims',json_build_object('sub',outsider,'role','authenticated')::text,true) from fixture;
set local role authenticated;
select pg_temp.ok('foreign tenant cannot list reports or audit',(select count(*)=0 from public.vacancy_reports) and (select count(*)=0 from public.vacancy_report_events));
select pg_temp.denied('foreign tenant cannot read by guessed ID',$q$select public.access_vacancy_report(company,current_setting('test.report')::uuid,'view') from fixture$q$,'42501');
select pg_temp.denied('foreign tenant cannot download by guessed ID',$q$select public.access_vacancy_report(company,current_setting('test.report')::uuid,'pdf') from fixture$q$,'42501');
reset role;
delete from public.company_members where user_id=(select viewer from fixture);
select set_config('request.jwt.claims',json_build_object('sub',viewer,'role','authenticated')::text,true) from fixture;
set local role authenticated;
select pg_temp.ok('revoked membership immediately blocks metadata',(select count(*)=0 from public.vacancy_reports));
select pg_temp.denied('revoked old JWT cannot read report',$q$select public.access_vacancy_report(company,current_setting('test.report')::uuid,'view') from fixture$q$,'42501');
reset role;
select set_config('request.jwt.claims',json_build_object('sub',actor,'role','authenticated')::text,true) from fixture;
update public.company_members set role='recruiter' where user_id=(select actor from fixture);
set local role authenticated;
select pg_temp.ok('RH can export',public.access_vacancy_report(company,current_setting('test.report')::uuid,'csv')->>'access_id' is not null) from fixture;
reset role;
update public.company_members set role='admin' where user_id=(select actor from fixture);
set local role authenticated;
select pg_temp.ok('admin can export',public.access_vacancy_report(company,current_setting('test.report')::uuid,'pdf')->>'access_id' is not null) from fixture;
select public.archive_candidate(company,candidate) from fixture;
select pg_temp.ok('archived candidate makes whole report unavailable',(select count(*)=0 from public.vacancy_reports));
select pg_temp.denied('archived candidate report cannot be downloaded',$q$select public.access_vacancy_report(company,current_setting('test.report')::uuid,'pdf') from fixture$q$,'42501');
reset role;
select pg_temp.ok('archiving preserves immutable snapshots and audit for retention',(select count(*)=2 from public.vacancy_reports) and (select count(*)>=8 from public.vacancy_report_events));
set local role anon;
select pg_temp.denied('anonymous cannot invoke report endpoint',$q$select public.access_vacancy_report(null,null,'view')$q$,'42501');
reset role;
select json_build_object('passed',count(*),'tests',json_agg(name)) from results;
rollback;
